namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Name { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = new();
    public Instructor Instructor { get; set; } = new();
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string FullName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Z]{2}\d{6}$", ErrorMessage = "Student ID must be 2 uppercase letters followed by 6 digits (e.g., CS123456).")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    List<Department> GetDepartments();
    List<Course> GetAllCourses();
    List<Course> GetFeaturedCourses();
    List<Course> SearchCourses(string? searchTerm, int? departmentId);
    Course? GetCourseById(int id);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, quantities, shapes, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language arts." }
        };

        var instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Associate Professor", Bio = "Dr. Chen specializes in algorithms and data structures with over 15 years of teaching experience. She has published extensively in computational complexity theory.", Email = "s.chen@university.edu" },
            new() { Id = 2, Name = "Dr. Michael Torres", Title = "Professor", Bio = "Dr. Torres is a leading researcher in artificial intelligence and machine learning. He previously worked at major tech companies before joining academia.", Email = "m.torres@university.edu" },
            new() { Id = 3, Name = "Dr. Emily Watson", Title = "Assistant Professor", Bio = "Dr. Watson focuses on abstract algebra and number theory. She received her PhD from MIT and has won multiple teaching awards.", Email = "e.watson@university.edu" },
            new() { Id = 4, Name = "Dr. James Liu", Title = "Professor", Bio = "Dr. Liu is an expert in quantum mechanics and particle physics. His research group has contributed to several breakthrough discoveries.", Email = "j.liu@university.edu" },
            new() { Id = 5, Name = "Dr. Rachel Green", Title = "Associate Professor", Bio = "Dr. Green specializes in modern American literature and creative writing. She is an award-winning author of three novels.", Email = "r.green@university.edu" },
            new() { Id = 6, Name = "Dr. David Park", Title = "Assistant Professor", Bio = "Dr. Park researches distributed systems and cloud computing. He brings industry experience from leading engineering teams.", Email = "d.park@university.edu" },
            new() { Id = 7, Name = "Dr. Lisa Kumar", Title = "Professor", Bio = "Dr. Kumar is a renowned statistician with expertise in probability theory and stochastic processes.", Email = "l.kumar@university.edu" },
            new() { Id = 8, Name = "Dr. Robert Hayes", Title = "Associate Professor", Bio = "Dr. Hayes studies thermodynamics and classical mechanics. He is known for his engaging lecture style and innovative lab exercises.", Email = "r.hayes@university.edu" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Name = "Introduction to Computer Science", Description = "A broad introduction to computer science covering programming fundamentals, algorithms, data representation, and computational thinking. Students will learn Python and develop problem-solving skills applicable across disciplines.", Credits = 3, Schedule = "MWF 10:00-10:50 AM", DepartmentId = 1, Department = _departments[0], Instructor = instructors[0], IsFeatured = true },
            new() { Id = 2, Code = "CS 301", Name = "Artificial Intelligence", Description = "Explore the foundations of AI including search algorithms, knowledge representation, machine learning, neural networks, and natural language processing. Includes hands-on projects building intelligent agents.", Credits = 4, Schedule = "TTh 1:00-2:20 PM", DepartmentId = 1, Department = _departments[0], Instructor = instructors[1], IsFeatured = true },
            new() { Id = 3, Code = "CS 250", Name = "Distributed Systems", Description = "Study of distributed computing principles including consensus algorithms, replication, fault tolerance, and scalable architectures. Students build distributed applications using modern frameworks.", Credits = 3, Schedule = "MWF 2:00-2:50 PM", DepartmentId = 1, Department = _departments[0], Instructor = instructors[5], IsFeatured = false },
            new() { Id = 4, Code = "MATH 201", Name = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and inner product spaces. Essential for advanced work in science and engineering.", Credits = 4, Schedule = "MWF 9:00-9:50 AM", DepartmentId = 2, Department = _departments[1], Instructor = instructors[2], IsFeatured = true },
            new() { Id = 5, Code = "MATH 310", Name = "Probability and Statistics", Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis. Applications drawn from science, engineering, and social sciences.", Credits = 3, Schedule = "TTh 10:30-11:50 AM", DepartmentId = 2, Department = _departments[1], Instructor = instructors[6], IsFeatured = false },
            new() { Id = 6, Code = "PHYS 101", Name = "General Physics I", Description = "Covers classical mechanics, including kinematics, Newton's laws, energy, momentum, rotational motion, and gravitation. Calculus-based approach with weekly laboratory sessions.", Credits = 4, Schedule = "MWF 11:00-11:50 AM", DepartmentId = 3, Department = _departments[2], Instructor = instructors[7], IsFeatured = false },
            new() { Id = 7, Code = "PHYS 305", Name = "Quantum Mechanics", Description = "Introduction to quantum theory including wave-particle duality, Schrödinger equation, hydrogen atom, angular momentum, and spin. Prerequisites: Physics II and Differential Equations.", Credits = 4, Schedule = "TTh 3:00-4:20 PM", DepartmentId = 3, Department = _departments[2], Instructor = instructors[3], IsFeatured = true },
            new() { Id = 8, Code = "ENG 102", Name = "Creative Writing", Description = "Workshop-based course exploring fiction, poetry, and creative nonfiction. Students develop their voice through weekly writing exercises, peer workshops, and revision strategies.", Credits = 3, Schedule = "TTh 9:00-10:20 AM", DepartmentId = 4, Department = _departments[3], Instructor = instructors[4], IsFeatured = false },
            new() { Id = 9, Code = "ENG 215", Name = "American Literature", Description = "Survey of American literature from the colonial period to the present. Examines major authors, literary movements, and cultural contexts that shaped the American literary tradition.", Credits = 3, Schedule = "MWF 1:00-1:50 PM", DepartmentId = 4, Department = _departments[3], Instructor = instructors[4], IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.ToLower();
            query = query.Where(c =>
                c.Name.ToLower().Contains(term) ||
                c.Code.ToLower().Contains(term) ||
                c.Description.ToLower().Contains(term));
        }

        return query.ToList();
    }

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);
}

