@page "/"
@inject ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="hero-section">
    <h1>University Course Catalog</h1>
    <p class="hero-subtitle">Explore our diverse range of courses and find the perfect fit for your academic journey.</p>
    <a href="/courses" class="btn-primary">Browse All Courses</a>
</div>

<section class="featured-section">
    <h2>Featured Courses</h2>
    <div class="course-cards">
        @foreach (var course in featuredCourses)
        {
            <div class="course-card">
                <span class="course-code">@course.Code</span>
                <h3><a href="/courses/@course.Id">@course.Name</a></h3>
                <p class="course-dept">@course.Department.Name</p>
                <p class="course-credits">@course.Credits credits &bull; @course.Schedule</p>
            </div>
        }
    </div>
</section>

<section class="departments-section">
    <h2>Departments</h2>
    <div class="department-list">
        @foreach (var dept in departments)
        {
            <div class="department-card">
                <h3><a href="/courses?DepartmentId=@dept.Id">@dept.Name</a></h3>
                <p>@dept.Description</p>
            </div>
        }
    </div>
</section>

@code {
    private List<Course> featuredCourses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = CatalogService.GetFeaturedCourses();
        departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@inject ICatalogService CatalogService

<PageTitle>Course Catalog - University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="/courses" class="search-form">
    <div class="search-controls">
        <input type="text" name="Search" value="@Search" placeholder="Search by name or keyword..." class="search-input" />
        <select name="DepartmentId" class="search-select">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
        <button type="submit" class="btn-primary">Search</button>
    </div>
</form>

@if (courses.Any())
{
    <table class="courses-table">
        <thead>
            <tr>
                <th>Code</th>
                <th>Course Name</th>
                <th>Department</th>
                <th>Credits</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Name</td>
                    <td>@course.Department.Name</td>
                    <td>@course.Credits</td>
                    <td><a href="/courses/@course.Id">View Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}
else
{
    <p class="no-results">No courses found. Try adjusting your search criteria.</p>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public int? DepartmentId { get; set; }

    private List<Course> courses = new();
    private List<Department> departments = new();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        courses = CatalogService.SearchCourses(Search, DepartmentId);
    }
}

@page "/enroll"
@inject ICatalogService CatalogService

<PageTitle>Enroll - University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="confirmation-message">
        <h2>Enrollment Request Submitted!</h2>
        <p>Thank you, <strong>@Model.FullName</strong>. Your enrollment request for the selected course has been received.</p>
        <p>Student ID: <strong>@Model.StudentId</strong></p>
        <p>We will process your request and send a confirmation to your university email.</p>
        <a href="/courses" class="btn-primary">Browse More Courses</a>
    </div>
}
else
{
    <p>Fill out the form below to request enrollment in a course.</p>

    <EditForm Model="Model" FormName="enrollment" method="post" Enhance OnValidSubmit="HandleSubmit">
        <DataAnnotationsValidator />
        <ValidationSummary />

        <div class="form-group">
            <label for="fullName">Full Name</label>
            <InputText id="fullName" @bind-Value="Model.FullName" class="form-control" />
            <ValidationMessage For="() => Model.FullName" />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g., CS123456" />
            <ValidationMessage For="() => Model.StudentId" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-control">
                <option value="0">-- Select a course --</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id">@course.Code - @course.Name</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" />
        </div>

        <button type="submit" class="btn-primary">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    public EnrollmentRequest Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<Course> courses = new();
    private bool submitted = false;

    protected override void OnInitialized()
    {
        courses = CatalogService.GetAllCourses();
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        submitted = true;
    }
}

